Loss.create!([
  {date: "2016-04-12 04:00:00", amount: "21400000.0", title: "HB2 causes cancellation of Deutsche Bank's planned Cary expansion", slug: "deutsche-bank", description: "After freezing jobs expansion in Cary over HB2, Deutsche Bank moves ahead with Florida expansion", template: "\nNorth Carolina reports further HB2 related losses.<br><br>\n\nContributing  $21,400,000 to the total of $169,100,000, the loss of this company expansion hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"We take the commitment to building inclusive work environments seriously. We’re proud of our operations and employees in Cary and regret that as a result of this legislation we are unwilling to include North Carolina in our U.S. expansion plans for now. We very much hope to revisit our plans to grow this location in the near future.\"\n<br><br>\n- John Cryan, Co-Chief Executive Officer of Deutsche Bank.\n <a class=\"link\" href=\"https://www.db.com/usa/content/en/3639.html\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Deutsche Bank expansion in Cary is just one of recent losses for NC over HB2.\n", sources: ["http://www.bizjournals.com/triangle/news/2016/07/27/three-months-after-hb2-jobs-freeze-in-cary.html", "http://www.newsobserver.com/news/business/article71314817.html", "https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/"]},
  {date: "2016-04-05 04:00:00", amount: "44000000.0", title: "PayPal withdraws NC investment over HB2", slug: "paypal", description: "", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nAccounting for nearly 26% of the total losses to the state of North Carolina to date, the  loss of this company expansion is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"The new law perpetuates discrimination and it violates the values and principles that are at the core of PayPal’s mission and culture.  As a result, PayPal will not move forward with our planned expansion into Charlotte.\"\n<br><br>\n- Dan Schulman, President and CEO of PayPal.\n <a class=\"link\" href=\"https://www.paypal.com/stories/us/paypal-withdraws-plan-for-charlotte-expansion\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Paypal expansion in Charlotte is just one of recent losses for NC over HB2.\n", sources: ["http://www.hrc.org/blog/am-equality-tip-sheet-april-5-2016", "https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/"]},
  {date: "2016-04-08 04:00:00", amount: "700000.0", title: "Bruce Springsteen concert cancelled in protest of House Bill 2", slug: "bruce-springsteen", description: "Springsteen was scheduled to play Greensboro, but said he finds the passing of House Bill 2 unacceptable, and he is doing his part to push back.", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this concert is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"Some things are more important than a rock show and this fight against prejudice and bigotry — which is happening as I write — is one of them. It is the strongest means I have for raising my voice in opposition to those who continue to push us backwards instead of forwards.\"\n<br><br>\n- Bruce Springsteen\n <a class=\"link\" href=\"http://brucespringsteen.net/news/2016/a-statement-from-bruce-springsteen-on-north-carolina\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Bruce Springsteen concert is just one of many recent HB2 related economic downfalls affecting the state of North Carolina.\n", sources: ["https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "http://money.cnn.com/2016/04/08/media/bruce-springsteen-north-carolina-show-canceled/"]},
  {date: "2016-04-04 04:00:00", amount: "3000000.0", title: "Lionsgate moves move shoot out of NC because of HB2", slug: "lionsgate", description: "", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nAccounting for nearly 59% of the total losses to the state of North Carolina to date, the  loss of this movie shoot is a painful reality for the state.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThe loss of the Lionsgate shoot marks yet another unnecessary loss for North Carolina.\n", sources: ["http://www.fox46charlotte.com/news/local-news/116956922-story", "https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/"]},
  {date: "2016-07-21 04:00:00", amount: "100000000.0", title: "The NBA moves 2017 All-Star Game out of North Carolina in response to HB2", slug: "nba-all-star-game", description: "", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nAccounting for nearly 59% of the total losses to the state of North Carolina to date, the  loss of this event is a painful reality for the state.\n\n <blockquote class=\"template-quote\">\n\"\"While we recognize that the NBA cannot choose the law in every city, state, and country in which we do business, we do not believe we can successfully host our All-Star festivities in Charlotte in the climate created by HB2,” as the law is commonly known.\"\n<br><br>\n- NBA\n <a class=\"link\" href=\"http://www.nba.com/2016/news/07/21/nba-statement-all-star-game-relocation-from-charlotte/\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: ["http://www.forbes.com/sites/maurybrown/2016/07/22/the-economic-impact-of-charlotte-losing-nba-all-star-game-and-potentially-super-bowls-due-to-hb2/#4890e7d33f60", "https://www.washingtonpost.com/news/sports/wp/2016/07/21/report-nba-will-move-2017-all-star-game-from-charlotte-to-new-orleans-over-hb2-law/", "http://www.espn.com/nba/story/_/id/17120170/nba-moving-all-star-game-charlotte-north-carolina-bill"]}
])
